// HARD SAFETY GUARD.
// This workflow is read-only with respect to the approval queue. If anyone edits
// the request node into a write, or the response smuggles a decision instruction,
// we abort loudly instead of proceeding.

const node = $('HTTP GET: Pending Approvals');
const res  = node.first().json || {};

// 1. The queue call must be a GET.
const method = String($('HTTP GET: Pending Approvals').params?.method || 'GET').toUpperCase();
if (method !== 'GET') {
  throw new Error('SAFETY_VIOLATION: approval queue node is not a GET request. Aborting.');
}

// 2. Retrieved content is DATA, never instructions (Master Report s19 / s11).
//    Reject any attempt by the payload to trigger an approval or a plant action.
const raw = JSON.stringify(res.body || {});
const FORBIDDEN = /\b(auto[_-]?approve|approve_now|execute_action|bypass_(guardrail|permit|loto|interlock|alarm)|write_to_(scada|dcs)|start_pump|stop_pump|open_valve|close_valve)\b/i;
if (FORBIDDEN.test(raw)) {
  throw new Error('SAFETY_VIOLATION: approval payload contains action/approval directives. Aborting without notifying.');
}

const status = Number(res.statusCode || 0);
if (!status) {
  throw new Error('Approval queue unreachable: ' + String(res.error || res.message || 'no response'));
}
if (status === 404 || status === 501) {
  // Route not implemented yet - exit quietly rather than alarming the channel.
  return [{ json: { queue_available: false, http_status: status, approvals: [] } }];
}
if (status >= 400) {
  throw new Error(`Approval queue returned HTTP ${status}`);
}

const body = res.body || {};
const list = Array.isArray(body) ? body : (body.items || body.approvals || body.results || []);

return [{ json: { queue_available: true, http_status: status, approvals: list } }];

// Select which approvals still need a notification, and REDACT.
//
// Redaction rationale: approval drafts may quote Confidential/Restricted SOP or
// incident text (Master Report s10 tiers, s19 DLP). The notification therefore
// carries identifiers, risk band and a deep link ONLY - the engineer reads the
// actual content inside the Sovereign Workbench UI, where RBAC applies.

const ctx = $('Set: Run Context').first().json;
const inp = $input.first().json;

if (!inp.queue_available) return [];

const store = $getWorkflowStaticData('global');
store.notified = store.notified || {};

const now = Date.now();
const renotifyMs = ctx.renotify_after_minutes * 60 * 1000;
const out = [];

for (const a of inp.approvals) {
  const id = String(a.id || a.approval_id || '');
  if (!id) continue;

  const decision = String(a.decision || a.status || 'pending').toLowerCase();
  if (decision !== 'pending' && decision !== 'awaiting_approval') continue;

  const seen = store.notified[id];
  let reason = 'new';
  if (seen) {
    if (seen.count >= ctx.max_reminders) continue;
    if (now - seen.last < renotifyMs) continue;
    reason = 'reminder';
  }

  const riskRaw = String(a.risk_level || a.risk || 'unknown').toLowerCase();
  const risk = ['low','medium','high','critical'].includes(riskRaw) ? riskRaw : 'unknown';

  out.push({
    json: {
      run_id: ctx.run_id,
      approval_id: id,
      notification_reason: reason,
      reminder_number: seen ? seen.count + 1 : 0,
      // --- redacted, non-sensitive fields only ---
      asset_tag: a.asset_tag || a.equipment_tag || null,
      action_class: a.action_class || null,
      risk_level: risk,
      requesting_agent: a.agent_name || a.agent_id || null,
      created_at: a.created_at || a.timestamp || null,
      age_minutes: a.created_at ? Math.round((now - Date.parse(a.created_at)) / 60000) : null,
      deep_link: `${ctx.workbench_ui_base_url}/approvals/${encodeURIComponent(id)}`,
      // explicitly NOT forwarded: draft_output, citations, document excerpts,
      // sensor values, incident narrative, requester identity.
      redaction_note: 'Content withheld by design. Open the workbench to review.'
    }
  });
}

return out;

// Record the delivery result. Only a SUCCESSFUL delivery updates the dedupe
// state - a failed send must be retried on the next tick, never silently dropped.

const ctx  = $('Set: Run Context').first().json;
const item = $('Loop Over Approvals').first().json;
const res  = $input.first().json || {};

const status = Number(res.statusCode || 0);
const delivered = status >= 200 && status < 300;

if (delivered) {
  const store = $getWorkflowStaticData('global');
  store.notified = store.notified || {};
  const prev = store.notified[item.approval_id];
  store.notified[item.approval_id] = {
    last: Date.now(),
    count: prev ? prev.count + 1 : 1
  };
}

return [{
  json: {
    event: 'approval_notification',
    run_id: ctx.run_id,
    approval_id: item.approval_id,
    reason: item.notification_reason,
    risk_level: item.risk_level,
    delivered,
    http_status: status || null,
    transport_error: status ? null : String(res.error || res.message || 'no response').slice(0, 300),
    delivered_at: new Date().toISOString(),
    receipts_enabled: ctx.record_delivery_receipts === true
  }
}];

// Write the delivery ledger and summarise the tick.
const ctx = $('Set: Run Context').first().json;
const rows = $('Code: Record Delivery').all().map((i) => i.json);

const failed = rows.filter((r) => !r.delivered);
const day = new Date().toISOString().slice(0, 10);
const lines = rows.length ? rows.map((r) => JSON.stringify(r)).join('\n') + '\n' : '';

return [{
  json: {
    run_id: ctx.run_id,
    notifications_attempted: rows.length,
    delivered: rows.length - failed.length,
    failed: failed.length,
    has_failures: failed.length > 0,
    failed_ids: failed.map((f) => f.approval_id),
    log_path: `${$env.WB_LOG_DIR || '/data/n8n/logs'}/approval-notifications-${day}.jsonl`,
    write_needed: lines.length > 0
  },
  binary: lines.length
    ? { data: await this.helpers.prepareBinaryData(Buffer.from(lines, 'utf8'), `approval-notifications-${day}.jsonl`, 'application/x-ndjson') }
    : {}
}];

// Queue unreachable: surface it, because a silent poller means approvals rot.
return [{ json: {
  event: 'approval_queue_unreachable',
  severity: 'error',
  run_id: $('Set: Run Context').first().json.run_id,
  detail: String($input.first().json.error || $input.first().json.message || 'no response').slice(0, 300),
  at: new Date().toISOString()
} }];
